import json
from docx import Document

template_path = '/root/offer_letter_template.docx'
output_path = '/root/offer_letter_filled.docx'

data = json.load(open('/root/employee_data.json'))

relocation_yes = str(data.get('RELOCATION_PACKAGE','')).strip().lower() in {'yes','y','true','1'}


def iter_paragraphs_from_container(container):
    for p in container.paragraphs:
        yield p
    for table in container.tables:
        for row in table.rows:
            for cell in row.cells:
                for p in cell.paragraphs:
                    yield p
                for nested_table in cell.tables:
                    # nested tables handled by recursion via container.tables? not for cell
                    for r in nested_table.rows:
                        for c in r.cells:
                            for p in c.paragraphs:
                                yield p


def iter_all_paragraphs(doc):
    # main document
    for p in iter_paragraphs_from_container(doc):
        yield p
    # headers/footers
    for section in doc.sections:
        for hf in (section.header, section.footer):
            for p in iter_paragraphs_from_container(hf):
                yield p


def delete_paragraph(paragraph):
    p = paragraph._element
    parent = p.getparent()
    if parent is not None:
        parent.remove(p)
    paragraph._p = paragraph._element = None


for p in list(iter_all_paragraphs(Document(template_path))):
    pass

# Reload document for actual edits

doc = Document(template_path)

for p in list(iter_all_paragraphs(doc)):
    text = ''.join(run.text for run in p.runs)
    if not text or '{{' not in text:
        continue
    original = text
    # handle relocation conditional
    if '{{IF_RELOCATION}}' in text or '{{END_IF_RELOCATION}}' in text:
        if relocation_yes:
            text = text.replace('{{IF_RELOCATION}}','').replace('{{END_IF_RELOCATION}}','')
        else:
            # remove content between markers if both in same paragraph
            # If markers appear, drop paragraph
            delete_paragraph(p)
            continue
    # replace placeholders
    for k, v in data.items():
        placeholder = '{{' + k + '}}'
        if placeholder in text:
            text = text.replace(placeholder, str(v))
    if text != original:
        if p.runs:
            p.runs[0].text = text
            for r in p.runs[1:]:
                r.text = ''
        else:
            p.add_run(text)

# Save

doc.save(output_path)
print('saved', output_path)
PY"}

